INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_baked-ziti-italian-sausage_v1', 'rcp_baked-ziti-italian-sausage', 'baked-ziti-italian-sausage', 1, 'Baked Ziti with Italian Sausage', 'Ziti tossed in a garlicky crushed-tomato and browned Italian sausage sauce with mozzarella, layered with pockets of basil-seasoned ricotta, topped with more mozzarella and Parmesan, and baked until bubbling and golden.', 4, 10, 52, 62, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high to brown, gentle simmer for the sauce, 400°F oven upper-middle rack (preheat overlaps prep and sauce).', 'Sausage browned with no pink. Pasta just under al dente before baking, tender after. Sauce bubbling at the edges; mozzarella melted with golden-brown spots; ricotta pockets creamy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"sausage-tomato-sauce","name":"Italian sausage tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["Italian sausage","olive oil","onion","garlic","dried oregano","red pepper flakes","crushed tomatoes","kosher salt"]},{"component_id":"basil-ricotta","name":"seasoned basil ricotta","made_in_recipe":true,"store_bought":false,"ingredients":["whole-milk ricotta","basil","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '4cc7e6ceedb9ae5830c2720530968fe4c3c68432635ac38ba9349a95aa459b61', 'flavorweave-catalog-package', 'catalog/baked-ziti-italian-sausage/v1.json', '2026-10-04T00:00:00.000Z');
