INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_brazilian-fish-moqueca_v1', 'rcp_brazilian-fish-moqueca', 'brazilian-fish-moqueca', 1, 'Brazilian Fish Moqueca', 'Lime-and-garlic-marinated halibut layered with onion, red and yellow pepper rings, and tomato, then gently simmered in coconut milk with sweet paprika and olive oil until just flaky; finished with lime and cilantro and served over white rice. A Bahian-style coconut moqueca made with olive oil instead of dende. White fish only; no shrimp or shellfish.', 4, 15, 25, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium sauté, then gentle covered simmer at medium-low. Rice on high then low. No oven.', 'Fish opaque and flaking at the thickest part (145°F), still moist. Peppers tender with rings intact. Broth creamy, coral-colored, and bright with lime. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lime-garlic-marinade","name":"lime-garlic-paprika fish marinade","made_in_recipe":true,"store_bought":false,"ingredients":["lime juice","garlic","sweet paprika","kosher salt","black pepper"]},{"component_id":"coconut-moqueca","name":"layered coconut moqueca","made_in_recipe":true,"store_bought":false,"ingredients":["halibut","onion","red and yellow bell peppers","tomatoes","chile","coconut milk","olive oil","cilantro","garlic","sweet paprika"]},{"component_id":"white-rice-cooked","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, '579c986ff149b9451f5ed2403197ffe53865241793f060ee2a9bc6f591730ff4', 'flavorweave-catalog-package', 'catalog/brazilian-fish-moqueca/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cajun-blackened-catfish_v1', 'rcp_cajun-blackened-catfish', 'cajun-blackened-catfish', 1, 'Cajun Blackened Catfish with Herb Remoulade', 'Catfish fillets coated in Cajun blackening spices and seared hard in a hot skillet, served with a dairy-free herb remoulade.', 4, 12, 17, 29, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Skillet preheated over medium-high until very hot. Blacken over medium-high. No oven. No grill required.', 'Spice crust darkened (blackened) and fragrant, not raw-spice pale and not incinerated ash. Fish opaque and flakes at the thickest point, about 145 F. Remoulade cold and spoonable. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"cajun-blackening-rub","name":"Cajun blackening rub","made_in_recipe":true,"store_bought":false,"ingredients":["sweet paprika","cayenne pepper","garlic powder","onion powder","dried thyme","dried oregano","kosher salt","black pepper"]},{"component_id":"herb-remoulade","name":"dairy-free herb remoulade","made_in_recipe":true,"store_bought":false,"ingredients":["egg mayonnaise","Dijon mustard","lemon juice","neutral oil","dill pickle relish","capers","fresh parsley","fresh chives","garlic","hot sauce","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'f6f9000f85acd078d6220d96465402869319d655fdf98f7da0cd3f9140fbec97', 'flavorweave-catalog-package', 'catalog/cajun-blackened-catfish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cashew-chicken-stir-fry_v1', 'rcp_cashew-chicken-stir-fry', 'cashew-chicken-stir-fry', 1, 'Cashew Chicken Stir-Fry', 'Takeout-style cashew chicken at home: cornstarch-velveted chicken breast seared in a hot skillet with red bell pepper, celery, onion, garlic, and ginger, glossed in a savory-sweet soy-hoisin sauce, and tossed with toasted cashews and scallions over jasmine rice.', 4, 15, 18, 33, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High to boil the rice, then low; medium dry skillet for the cashews; high heat for searing and stir-frying. No oven.', 'Chicken golden in spots and just cooked through (165 F). Vegetables crisp-tender with a few charred spots. Sauce glossy and lightly thick, coating rather than pooling. Cashews golden. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"velveted-chicken","name":"cornstarch-velveted seared chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken breast","soy sauce","dry sherry","cornstarch","neutral oil"]},{"component_id":"soy-hoisin-sauce","name":"soy-hoisin stir-fry sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","dry sherry","hoisin sauce","brown sugar","cornstarch","water"]},{"component_id":"cashew-vegetable-stir-fry","name":"cashew vegetable stir-fry","made_in_recipe":true,"store_bought":false,"ingredients":["red bell pepper","celery","yellow onion","scallions","garlic","fresh ginger","toasted cashews","toasted sesame oil"]},{"component_id":"jasmine-rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'd25d86a4609eea21ea2350e4010c18c54b5aaf26931fbeef9891c82e31d6f083', 'flavorweave-catalog-package', 'catalog/cashew-chicken-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
