INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chicken-enchiladas-verdes_v1', 'rcp_chicken-enchiladas-verdes', 'chicken-enchiladas-verdes', 1, 'Chicken Enchiladas Verdes', 'Broiler-charred tomatillos, jalapeños, onion, and garlic blended with cilantro and lime into a bright salsa verde; broiled cumin chicken thighs shredded with salsa and Monterey Jack, rolled in warm corn tortillas, smothered in more salsa and cheese, and baked until bubbling. Finished with lime crema, diced onion, radishes, and cilantro.', 4, 15, 47, 62, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High broiler (heats during prep), then 425°F bake.', 'Chicken 175°F and tender before shredding. Salsa bubbling at the edges, cheese melted with golden spots, tortillas soft (not dry at the ends). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"salsa-verde","name":"broiled tomatillo salsa verde","made_in_recipe":true,"store_bought":false,"ingredients":["tomatillos","white onion","jalapeños","garlic","cilantro","lime juice","kosher salt","water"]},{"component_id":"chicken-filling","name":"shredded cumin chicken filling","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","ground cumin","salsa verde","Monterey Jack"]},{"component_id":"lime-crema","name":"lime crema","made_in_recipe":true,"store_bought":false,"ingredients":["sour cream","lime juice","water"]}]', 'published', 'draft', 'global', NULL, '66ba530265c87cea6e3afefced150833767e9d9db06eec3a29b7ae2acf5ec782', 'flavorweave-catalog-package', 'catalog/chicken-enchiladas-verdes/v1.json', '2026-10-04T00:00:00.000Z');
