INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_chipotle-lime-black-bean-bowls_v2', 'rcp_chipotle-lime-black-bean-bowls', 'chipotle-lime-black-bean-bowls', 2, 'Chipotle Lime Black Bean Bowls', 'Black beans simmered with minced chipotle and lime, with quinoa and corn. No extra toppings.', 4, 10, 20, 30, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Stovetop simmer for quinoa and beans. No oven and no grill. Mild heat from 1 tsp minced chipotle across 4 servings.', 'Quinoa is done when the grains are tender, a white ring just shows, and the water is absorbed, about 15 minutes plus a 5-minute rest. Beans are done when hot and coated, about 10 minutes. They are not a soup.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '1e4b81cb3fb2be7f37d2dce68b2a9b4dbfd65bfc22e2643cea28934be5df5a2b', 'flavorweave-legacy-audit-draft', 'catalog/chipotle-lime-black-bean-bowls/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cider-braised-pork-shoulder_v1', 'rcp_cider-braised-pork-shoulder', 'cider-braised-pork-shoulder', 1, 'Cider-Braised Pork Shoulder with Mustard Cabbage', 'A long cider braise of pork shoulder, reduced to a spoon-coating sauce with apple, served with skillet mustard cabbage.', 4, 20, 192, 212, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Sear on the stove over medium-high, then a covered oven braise at 325 F. Sauce reduces at a boil. Cabbage skillet is medium.', 'Pork shoulder at 195-203 F in the center and fork-tender. 145 F is not done for this cut. Rest 15 minutes. Slice 1/2 inch against the grain if it holds; pull large chunks if it collapses. Do not puree it.', '[]', '[]', 'null', '[{"component_id":"cider-mustard-sauce","name":"cider-mustard sauce","made_in_recipe":true,"store_bought":false,"ingredients":["apple cider","water","dijon mustard","yellow onion","apple","garlic","fresh thyme"]},{"component_id":"mustard-cabbage","name":"mustard cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","olive oil","water","apple cider vinegar","dijon mustard","kosher salt"]}]', 'published', 'draft', 'global', NULL, '543e6e4d799aa2b8d1a414d94db5cba35d92645f15d3db4e2288d0a3b537c42a', 'flavorweave-catalog-package', 'catalog/cider-braised-pork-shoulder/v1.json', '2026-10-04T00:00:00.000Z');
