INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_peruvian-lomo-saltado_v1', 'rcp_peruvian-lomo-saltado', 'peruvian-lomo-saltado', 1, 'Peruvian Lomo Saltado', 'Soy-and-cumin-marinated sirloin strips seared hard in a smoking-hot skillet, tossed with charred red onion, juicy tomato wedges, garlic, and a fruity ají amarillo-vinegar-soy sauce, finished with cilantro and folded with crisp oven fries; served with white rice.', 4, 15, 25, 40, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', '425°F oven for fries (preheat overlaps prep); rice high then low; skillet on high, smoking hot, for the stir-fry.', 'Beef browned outside, pink and juicy inside (about medium). Onion edges charred but crisp. Tomatoes warmed, not collapsed. Fries deep golden and crisp. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"beef-marinade","name":"soy-garlic-cumin beef marinade","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","garlic","ground cumin","black pepper"]},{"component_id":"aji-saltado-sauce","name":"ají amarillo-vinegar-soy sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","red wine vinegar","ají amarillo paste"]},{"component_id":"oven-fries","name":"oven-baked fries","made_in_recipe":true,"store_bought":false,"ingredients":["frozen straight-cut French fries"]},{"component_id":"white-rice-cooked","name":"steamed white rice","made_in_recipe":true,"store_bought":false,"ingredients":["long-grain white rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, '108ee6c6fde7a793346f27d10b8fe697480763a3530313a97d8d15b36550c75a', 'flavorweave-catalog-package', 'catalog/peruvian-lomo-saltado/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_potato-leek-gratin_v1', 'rcp_potato-leek-gratin', 'potato-leek-gratin', 1, 'Potato and Leek Gratin', 'Thinly sliced potatoes and leeks baked in a cream and cheese custard until the center is tender and the top is browned.', 4, 15, 55, 70, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven 400 F. Leeks sauté over medium during the preheat. Bake on the middle rack.', 'Center potato slice takes a knife with little resistance. Cream is bubbling at the edges and thickened, not watery. Cheese on top is browned in patches. No breadcrumb crust. Rest 5 minutes. Written bake is 40 minutes at 400 F for 1/8-inch slices. kitchen_tested is false. Extra time beyond 40 minutes, if the center is still firm, is not included in the 70-minute total.', '[]', '[]', 'null', '[{"component_id":"cream-cheese-custard","name":"cream-cheese custard","made_in_recipe":true,"store_bought":false,"ingredients":["heavy cream","vegetarian Gruyère","garlic","kosher salt","black pepper","ground nutmeg","fresh thyme"]}]', 'published', 'draft', 'global', NULL, '6f7addeef404ad541177eb096a8a78dc077bda23867edaccf7c67f25c5d3bb90', 'flavorweave-catalog-package', 'catalog/potato-leek-gratin/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pressure-cooker-butter-chicken_v1', 'rcp_pressure-cooker-butter-chicken', 'pressure-cooker-butter-chicken', 1, 'Pressure-Cooker Butter Chicken', 'Tender chicken thigh pieces in a silky, gently spiced tomato-butter-cream sauce made in an electric pressure cooker: onion, garlic, and ginger bloomed in butter with garam masala and paprika, pressure-cooked with tomato puree, then finished with cream and a last knob of butter. Served with fluffy basmati rice and cilantro.', 4, 15, 37, 52, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Electric pressure cooker: Sauté (high) for butter and aromatics; Pressure Cook High 5 minutes with 5-minute natural release; Sauté to finish with cream. Stovetop saucepan for rice: boil, then low. No oven.', 'Chicken very tender, at least 165 F (175 F ideal for thighs); sauce thick enough to coat a spoon, glossy after the cold butter; no raw spice taste. Rice tender and fluffy with separate grains. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"butter-chicken","name":"pressure-cooker butter chicken","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","kosher salt","garam masala","ground cumin","ground coriander","ground turmeric","sweet paprika","cayenne","unsalted butter","neutral oil","yellow onion","garlic","fresh ginger","water","tomato puree","heavy cream","sugar"]},{"component_id":"basmati-rice","name":"steamed basmati rice","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'd3d5014a545c565d50d6b0396b92c89429641e13b989fbe0888ca39b57940b4b', 'flavorweave-catalog-package', 'catalog/pressure-cooker-butter-chicken/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pumpkin-pinto-bean-chili_v1', 'rcp_pumpkin-pinto-bean-chili', 'pumpkin-pinto-bean-chili', 1, 'Smoky Pumpkin and Pinto Bean Chili', 'A thick, brick-red pinto bean chili built on smoked paprika, chili powder, and fire-roasted tomatoes, with canned pumpkin melted in for body and a gentle sweetness. Finished with lime and topped with diced avocado, radish, cilantro, and crushed corn tortilla chips. Plant-based; no cheese, no sour cream.', 4, 12, 33, 45, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Stovetop only. Medium to soften the onion and pepper; medium-high to return to a simmer; medium-low uncovered simmer. No oven.', 'Chili thick enough to mound on a spoon; beans tender and some crushed into the base; pumpkin fully melted into a brick-red, glossy chili; no raw spice taste. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"smoky-pumpkin-pinto-chili","name":"smoky pumpkin pinto bean chili","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","red bell pepper","garlic","chili powder","ground cumin","smoked paprika","ground chipotle","dried oregano","tomato paste","pumpkin puree","fire-roasted tomatoes","pinto beans","vegetable broth","kosher salt","lime juice"]},{"component_id":"fresh-toppings","name":"avocado, radish, cilantro, and tortilla-chip toppings","made_in_recipe":true,"store_bought":false,"ingredients":["avocados","radishes","cilantro","corn tortilla chips","lime wedges"],"contract":"Assembled from raw/whole ingredients; tortilla chips are store-bought with a plain-corn, non-peanut-oil contract."}]', 'published', 'draft', 'global', NULL, 'f4d299138ca21c4bc70b59343a44c92f1fa8ea1e790d41ecf8bcd99b52d2c7c1', 'flavorweave-catalog-package', 'catalog/pumpkin-pinto-bean-chili/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-butternut-farro-plate_v1', 'rcp_roasted-butternut-farro-plate', 'roasted-butternut-farro-plate', 1, 'Roasted Butternut Plate with Farro and Lemon-Herb Dressing', 'Oven-roasted butternut wedges beside simmered pearled farro, with a lemon, garlic, and parsley dressing spooned over the plate.', 4, 15, 35, 50, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven 425 F for the squash. Farro simmers on the stove. Dressing is not cooked.', 'Squash is done when the edges are browned and a knife meets no resistance, about 35 minutes, flipped at 20. Pearled farro is done when the grains are tender and some have split, about 30 minutes. This recipe is pearled farro only.', '[]', '[]', 'null', '[{"component_id":"lemon-herb-dressing","name":"lemon-herb dressing","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","lemon","garlic","dijon mustard","fresh parsley","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'b31a64f4553e5dd21984399d58b6460114886716fb6cb1f1d94b2c4484d5bf2f', 'flavorweave-catalog-package', 'catalog/roasted-butternut-farro-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-cauliflower-shawarma-plate_v1', 'rcp_roasted-cauliflower-shawarma-plate', 'roasted-cauliflower-shawarma-plate', 1, 'Roasted Cauliflower Shawarma Plate', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '8bdf1241bad9dc49cb37c607b50f33e5c9bdfc9d0fc265c9618d3dc9777d1df7', 'flavorweave-legacy-catalog-package', 'catalog/roasted-cauliflower-shawarma-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-cauliflower-shawarma-plate_v2', 'rcp_roasted-cauliflower-shawarma-plate', 'roasted-cauliflower-shawarma-plate', 2, 'Roasted Cauliflower Shawarma Plate', 'Oven-roasted cauliflower with store-bought shawarma spice, tahini and lemon drizzle, diced cucumber, and warm pita.', 4, 15, 25, 40, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Oven 425 F. The sauce is not cooked.', 'Cauliflower is done when the edges are charred and a stem is tender, about 25 minutes at 425 F.', '["oven"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'a8e8bae255345ed81bca7ff158ea70b20c7ad1da0936dd17e372fb960654117f', 'flavorweave-legacy-audit-draft', 'catalog/roasted-cauliflower-shawarma-plate/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_saag-paneer_v1', 'rcp_saag-paneer', 'saag-paneer', 1, 'Saag Paneer', 'Browned paneer cubes simmered in a spiced spinach (saag) skillet sauce finished with cream and butter.', 4, 18, 28, 46, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Boil for spinach blanch (inside prep). Skillet medium-high for paneer, then medium for the saag base and simmer. Finish cream on low/off-hard-boil.', 'Paneer golden on several faces, soft inside, not rubbery-dry. Saag thick enough to coat a spoon, spinach cooked and green-olive rather than raw. Cream stirred smooth. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spinach-saag","name":"spinach saag","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","yellow onion","garlic","fresh ginger","jalapeño","ground cumin","ground coriander","ground turmeric","garam masala","cayenne pepper","canned diced tomatoes","baby spinach","water","kosher salt","heavy cream","unsalted butter","lemon juice","fresh cilantro"]}]', 'published', 'draft', 'global', NULL, 'defbe233a1b14513accc3780910045721be66159b1c1d5e44d00f8e4476151c3', 'flavorweave-catalog-package', 'catalog/saag-paneer/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sabich-pita-sandwiches_v1', 'rcp_sabich-pita-sandwiches', 'sabich-pita-sandwiches', 1, 'Sabich Pita with Crispy Eggplant and Tahini', 'Warm pocket pitas spread with hummus and stuffed with golden pan-fried eggplant, sliced hard-boiled egg, a chopped tomato-cucumber salad, dill pickles, and parsley, then drizzled with garlicky lemon tahini. Dairy-free pita contracted; amba (mango pickle sauce) optional.', 4, 15, 28, 43, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high skillet for shallow-frying; boiling water for eggs; medium dry skillet to warm pitas. No oven.', 'Eggplant deep golden with crisp edges and fully creamy inside (no white, spongy centers). Eggs boiled 10 minutes: whites set, yolks firm but moist. Tahini pourable. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"crispy-eggplant","name":"pan-fried eggplant rounds","made_in_recipe":true,"store_bought":false,"ingredients":["eggplant","kosher salt","neutral oil"]},{"component_id":"hard-boiled-eggs","name":"hard-boiled eggs","made_in_recipe":true,"store_bought":false,"ingredients":["eggs"]},{"component_id":"lemon-tahini","name":"garlic lemon tahini sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tahini","lemon juice","garlic","kosher salt","cold water"]},{"component_id":"chopped-salad","name":"tomato-cucumber chopped salad","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","Persian cucumbers","parsley","lemon juice","olive oil","kosher salt"]},{"component_id":"store-bought-condiments","name":"hummus, dill pickles, optional amba","made_in_recipe":false,"store_bought":true,"ingredients":["hummus","dill pickles","amba"]}]', 'published', 'draft', 'global', NULL, 'c49dee4c088d9df638343c5d52159735ac839ec6ed047cf215d0f628ea3b8289', 'flavorweave-catalog-package', 'catalog/sabich-pita-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_salade-nicoise-seared-tuna_v1', 'rcp_salade-nicoise-seared-tuna', 'salade-nicoise-seared-tuna', 1, 'Salade Niçoise with Seared Tuna', 'A dinner-sized composed salad: pepper-crusted seared ahi tuna sliced rare, warm baby potatoes tossed in Dijon-shallot vinaigrette, jammy 7-minute eggs, crisp green beans, cherry tomatoes, olives, and capers on butter lettuce. Dairy-free vinaigrette; no butter anywhere.', 4, 15, 29, 44, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Stovetop only. High heat for the boiling water and a steady boil for potatoes/eggs/beans; high heat, shimmering oil for the tuna sear. No oven.', 'Potatoes knife-tender; eggs jammy (7 minutes from cold); beans bright green and crisp-tender; tuna seared on the outside with a deep-red rare center (about 115 F) or 145 F if cooked through by preference. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"dijon-shallot-vinaigrette","name":"Dijon-shallot vinaigrette (dairy-free)","made_in_recipe":true,"store_bought":false,"ingredients":["extra-virgin olive oil","red wine vinegar","Dijon mustard","shallot","garlic","kosher salt","black pepper"]},{"component_id":"one-pot-potatoes-eggs-beans","name":"warm vinaigrette potatoes, jammy eggs, and blanched green beans (one pot)","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","eggs","green beans","kosher salt","vinaigrette"]},{"component_id":"pepper-seared-tuna","name":"pepper-seared ahi tuna","made_in_recipe":true,"store_bought":false,"ingredients":["yellowfin tuna","neutral oil","kosher salt","black pepper"]},{"component_id":"composed-salad","name":"composed niçoise salad","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","cherry tomatoes","olives","capers","parsley","optional anchovies"]}]', 'published', 'draft', 'global', NULL, '61e64943e53406bc4a5a0533f916ac256e236e23f0a5052d4416abfb8706cea6', 'flavorweave-catalog-package', 'catalog/salade-nicoise-seared-tuna/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_seared-scallops-parsnip-puree_v1', 'rcp_seared-scallops-parsnip-puree', 'seared-scallops-parsnip-puree', 1, 'Seared Scallops with Parsnip Purée and Crispy Sage', 'Golden-crusted sea scallops on a silky, sweet parsnip purée, spooned with nutty sage brown butter and crisp-fried sage leaves, with a lemony baby arugula salad for brightness.', 4, 10, 37, 47, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium to bring the parsnips to a bare simmer, then gentle; medium for the brown butter; high, very hot skillet for searing; lowest heat to hold the purée.', 'Parsnips very tender; purée completely silky. Sage crisp and butter nutty brown, not black. Scallops with a deep golden-brown crust, just opaque at the edges, translucent in the center (120 to 125 F). For fully cooked scallops (recommended for young children, pregnant, older, or immunocompromised diners), cook 1 to 2 minutes longer on the second side until opaque throughout (145 F). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"parsnip-puree","name":"silky parsnip purée","made_in_recipe":true,"store_bought":false,"ingredients":["parsnips","whole milk","water","unsalted butter","kosher salt"]},{"component_id":"sage-brown-butter","name":"sage brown butter with crispy sage","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","fresh sage","kosher salt"]},{"component_id":"seared-scallops","name":"seared sea scallops","made_in_recipe":true,"store_bought":false,"ingredients":["sea scallops","neutral oil","kosher salt","black pepper"]},{"component_id":"lemony-arugula","name":"lemony arugula salad","made_in_recipe":true,"store_bought":false,"ingredients":["baby arugula","extra-virgin olive oil","lemon","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'b9031916ca627a108b05c7dcc45ec8a5063b66c7d1111a2692bdbea64fffcd9f', 'flavorweave-catalog-package', 'catalog/seared-scallops-parsnip-puree/v1.json', '2026-10-04T00:00:00.000Z');
