INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sesame-soba-noodle-bowl_v2', 'rcp_sesame-soba-noodle-bowl', 'sesame-soba-noodle-bowl', 2, 'Sesame Soba Noodle Bowl', 'Cold rinsed soba tossed with sesame oil, rice vinegar, and soy, topped with julienned carrot, edamame, and sesame seeds.', 4, 15, 10, 25, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Boiling water for the soba. The dressing is not cooked.', 'Soba is done when tender but not mushy, 4 to 5 minutes, then rinsed cold. Edamame is already cooked and only thawed.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '33d99cfe55c2e9b6329cef8d2a68d7b7f4eaef9a96079d42a3c1e70611969aaa', 'flavorweave-legacy-audit-draft', 'catalog/sesame-soba-noodle-bowl/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-gnocchi-brussels-apples_v1', 'rcp_sheet-pan-gnocchi-brussels-apples', 'sheet-pan-gnocchi-brussels-apples', 1, 'Sheet-Pan Crispy Gnocchi with Brussels Sprouts and Apples', 'Shelf-stable potato gnocchi roasted straight from the package until golden and crisp, with deeply browned Brussels sprouts, red onion, and apple wedges, finished in a sticky maple-Dijon-cider glaze with fresh thyme. Egg-free, dairy-free gnocchi contracted; no Parmesan, no butter, no nuts.', 4, 15, 30, 45, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', '450°F oven, two racks (upper-middle and lower-middle). Preheat overlaps prep.', 'Gnocchi puffed, golden, and crisp at the edges with soft centers. Sprouts deeply browned on cut sides and knife-tender. Apples browned at edges but holding shape. Glaze sticky, not pooled. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"maple-dijon-glaze","name":"maple-Dijon-cider glaze","made_in_recipe":true,"store_bought":false,"ingredients":["pure maple syrup","apple cider vinegar","Dijon mustard","fresh thyme","kosher salt"]},{"component_id":"roasted-gnocchi-sprouts-apples","name":"roasted gnocchi, sprouts, apples, and onion","made_in_recipe":true,"store_bought":false,"ingredients":["shelf-stable potato gnocchi (egg-free, dairy-free)","Brussels sprouts","crisp apples","red onion","olive oil","fresh thyme"]}]', 'published', 'draft', 'global', NULL, 'b748d8df97b73c4034f933a76f15461750c8a55b16334906d09eb244792caef0', 'flavorweave-catalog-package', 'catalog/sheet-pan-gnocchi-brussels-apples/v1.json', '2026-10-04T00:00:00.000Z');
