INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-margherita-pizza_v1', 'rcp_sheet-pan-margherita-pizza', 'sheet-pan-margherita-pizza', 1, 'Sheet-Pan Margherita Pizza', 'Store-bought pizza dough pressed into an olive-oiled sheet pan, topped with a simple crushed-tomato sauce and torn fresh mozzarella, baked hot until crisp underneath, and finished with fresh basil.', 4, 15, 44, 59, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 475 F, rack in the lower third, preheated about 20 minutes. Oiled heavy sheet pan directly on the rack — no pizza stone, no broiler, no grill.', 'Underside deep golden and crisp when a corner is lifted (not pale or doughy); edges golden and puffed. Fresh mozzarella melted, bubbling, lightly spotted — not separated into oil and not browned to rubber. Sauce reduced and jammy, not watery. Basil bright green, added after baking. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"sheet-pan-dough","name":"store-bought pizza dough base","made_in_recipe":false,"store_bought":true,"contract":"Store-bought raw pizza dough limited to wheat flour, water, yeast, salt, oil, optional sugar; no milk/egg/cheese/soy flour.","ingredients":["store-bought raw pizza dough","extra-virgin olive oil"]},{"component_id":"crushed-tomato-sauce","name":"uncooked crushed-tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["canned crushed tomatoes","garlic","extra-virgin olive oil","kosher salt"]},{"component_id":"margherita-topping","name":"fresh mozzarella and basil topping","made_in_recipe":true,"store_bought":false,"ingredients":["fresh mozzarella","fresh basil"]}]', 'published', 'draft', 'global', NULL, '9c6c13cb8b3fc5fe052cea4e5a54c5223952a87e7a752c530e2a24cc8b1ba887', 'flavorweave-catalog-package', 'catalog/sheet-pan-margherita-pizza/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-shrimp-boil_v1', 'rcp_sheet-pan-shrimp-boil', 'sheet-pan-shrimp-boil', 1, 'Sheet-Pan Shrimp Boil with Corn and Andouille', 'All the flavor of a Lowcountry boil without the boil: Old Bay–seasoned baby potatoes, red onion, corn rounds, and smoky andouille roast until browned, then garlic-Old Bay butter shrimp go on for the last few minutes. Finished with lemon and parsley, straight from the pans.', 4, 15, 35, 50, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Oven 425 F, racks in upper and lower thirds, preheated during the 15-minute prep. Pans switch racks when the corn goes in. Microwave only to melt the garlic butter.', 'Potatoes fork-tender and browned on the cut side; corn kernels spotted golden; andouille browned at the edges; shrimp pink, opaque, loosely C-shaped (145 F), not tightly curled. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"old-bay-sheet-pan-vegetables-and-sausage","name":"Old Bay roasted potatoes, onion, corn, and andouille","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","red onion","corn","andouille sausage","olive oil","Old Bay seasoning","kosher salt"]},{"component_id":"garlic-old-bay-butter-shrimp","name":"garlic Old Bay butter shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["shrimp","unsalted butter","garlic","Old Bay seasoning"]}]', 'published', 'draft', 'global', NULL, 'dcd0d345b574d9b77366ce09a2464ef13779e4d91253625d81e8d920a4c68f19', 'flavorweave-catalog-package', 'catalog/sheet-pan-shrimp-boil/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_skillet-shakshuka_v1', 'rcp_skillet-shakshuka', 'skillet-shakshuka', 1, 'Skillet Shakshuka', 'Eggs set in a skillet of tomato and red pepper sauce made from crushed tomatoes, peppers, onion, and ground spices.', 4, 12, 26, 38, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium for the onion, peppers, and sauce. Medium-low, covered, for the eggs. No oven.', 'Sauce holds a well after about 10 minutes of simmering. Eggs: whites fully set, no liquid white, yolks soft and glossy. Do not flip them. Firm yolks need about 2 extra covered minutes and are not the written target. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"tomato-pepper-sauce","name":"tomato-pepper sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","red bell pepper","garlic","sweet paprika","ground cumin","ground coriander","canned crushed tomatoes","water","sugar","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'b56017fba05a6fd07bca2595226312c9bdb20ae1aa71c318f215694ec9dd975e', 'flavorweave-catalog-package', 'catalog/skillet-shakshuka/v1.json', '2026-10-04T00:00:00.000Z');
