INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_smoky-lentil-sweet-potato-stew_v2', 'rcp_smoky-lentil-sweet-potato-stew', 'smoky-lentil-sweet-potato-stew', 2, 'Smoky Lentil Sweet Potato Stew', NULL, 4, 15, 25, 40, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', NULL, 'Sweet potato cubes tender when pierced. Red lentils broken down. Stew thick enough to mound slightly after a partial mash, not a thin broth.', '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'published', 'draft', 'global', NULL, '9eb6c1842c6e9e97dc75cafa0ace93f0d17d47b1cd6523a971bcdddc1b6d7dc5', 'flavorweave-legacy-catalog-package', 'catalog/smoky-lentil-sweet-potato-stew/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spaghetti-puttanesca_v1', 'rcp_spaghetti-puttanesca', 'spaghetti-puttanesca', 1, 'Spaghetti Puttanesca', 'Spaghetti tossed in a quick, punchy tomato sauce built on olive oil-melted anchovies, garlic, and chile flakes, with Kalamata olives and capers, finished with parsley and a last splash of olive oil. Egg-free dried pasta; no cheese, no butter.', 4, 10, 16, 26, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High heat for the pasta water; medium for the anchovy-garlic bloom; brisk simmer (medium to medium-high) for the sauce; medium-high to toss. No oven.', 'Anchovies fully dissolved; garlic pale gold, not brown. Sauce thick enough to cling, glossy with oil at the edges. Spaghetti al dente with sauce on every strand. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"puttanesca-sauce","name":"anchovy-olive-caper tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","anchovy fillets","garlic","red pepper flakes","tomato paste","whole peeled tomatoes","kalamata olives","capers","dried oregano"]},{"component_id":"spaghetti","name":"spaghetti cooked al dente","made_in_recipe":true,"store_bought":false,"ingredients":["spaghetti","salted water"]}]', 'published', 'draft', 'global', NULL, 'e7861ae73533cbfdfb1fb39f4cd8405f55ba156188b986e0e2d343eabbc2e18d', 'flavorweave-catalog-package', 'catalog/spaghetti-puttanesca/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 'rcp_spanish-chorizo-pepper-rice', 'spanish-chorizo-pepper-rice', 1, 'Spanish Chorizo and Pepper Rice', 'One-pan Spanish-style rice cooked with sliced cured chorizo, blistered peppers, onion, garlic, smoked paprika, and tomatoes.', 4, 12, 33, 45, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium for browning chorizo and peppers; medium-high to bring to simmer; low covered for absorb. No oven. No grill.', 'Rice tender and liquid absorbed after covered cook plus 5-minute rest. Peppers blistered at edges. Chorizo browned. No raw crunchy rice. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"chorizo-pepper-sofrito","name":"chorizo-pepper sofrito base","made_in_recipe":true,"store_bought":false,"ingredients":["Spanish chorizo","yellow onion","red bell pepper","green bell pepper","garlic","smoked paprika","ground cumin","olive oil"]},{"component_id":"one-pan-arroz","name":"one-pan Spanish-style rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","crushed tomatoes","stock","chorizo-pepper sofrito"]}]', 'published', 'draft', 'global', NULL, 'a6a09635408919abd854ae6f018194487a26739f855a39932c4d852cb72d8d6e', 'flavorweave-catalog-package', 'catalog/spanish-chorizo-pepper-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spiced-lamb-meatballs_v1', 'rcp_spiced-lamb-meatballs', 'spiced-lamb-meatballs', 1, 'Spiced Lamb Meatballs with Tomato-Herb Sauce', 'Lamb meatballs seasoned with cumin, coriander, mint, and parsley, browned and simmered in a skillet tomato-herb sauce.', 4, 18, 28, 46, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium-high to brown. Medium for sauce aromatics. Medium-low simmer for meatballs in sauce. No oven.', 'Meatball centers 160 F. Sauce slightly thickened, spoon-coating. Herbs fresh at the finish. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spiced-lamb-meatballs","name":"spiced lamb meatballs","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","egg","panko breadcrumbs","yellow onion","garlic","fresh parsley","fresh mint","ground cumin","ground coriander","sweet paprika","red pepper flakes","kosher salt","black pepper"]},{"component_id":"tomato-herb-sauce","name":"tomato-herb sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","garlic","tomato paste","canned crushed tomatoes","water","kosher salt","fresh parsley"]}]', 'published', 'draft', 'global', NULL, '340caffc461b9455aa207747cbf716a7d2792d3ef17cb672e4dd2ad713437f95', 'flavorweave-catalog-package', 'catalog/spiced-lamb-meatballs/v1.json', '2026-10-04T00:00:00.000Z');
