INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-basil-eggplant-stir-fry_v1', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 1, 'Thai Basil Eggplant Stir-Fry', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '29062adb3a9e3ea6b0411d3378cd7a58e2b0472e8e06199b9091ae0c6f3ea08e', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 2, 'Thai Basil Eggplant Stir-Fry', 'Browned Japanese eggplant and wilted Thai basil over jasmine rice, seasoned with soy sauce and garlic.', 4, 15, 25, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'none', 'Eggplant browned and tender, center creamy with no raw white spongy core. Basil wilted, not blackened. Rice tender.', '["stovetop"]', '["plant","dairy-free"]', '{"soy sauce":"Keep wheat-containing soy sauce. Wheat-free tamari would drop the wheat allergen and is not this version.","fish sauce":"Do not substitute fish sauce. It would drop the plant claim and add finfish."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, 'c07864661aac95b2f645c4a7357180a9a21d6c166b8389dfa88bcc543c455fc6', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-fish-cakes-cucumber-relish_v1', 'rcp_thai-fish-cakes-cucumber-relish', 'thai-fish-cakes-cucumber-relish', 1, 'Thai Fish Cakes with Cucumber Relish', 'Springy, curry-red Thai fish cakes of ground white fish, shrimp-paste-free red curry paste, fish sauce, lime, and sliced green beans, pan-fried until crisp at the edges and served with a sweet-sour cucumber-shallot relish and jasmine rice. No peanuts, no shellfish.', 4, 15, 28, 43, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'High to boil the rice, then low; medium-high skillet for shallow-frying. No oven.', 'Cakes puffed, deep golden with crisp edges, opaque and springy in the center (145 F). Rice tender and fluffy. Relish crisp, sweet-sour, and lightly hot. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"red-curry-fish-cakes","name":"red curry fish cakes","made_in_recipe":true,"store_bought":false,"ingredients":["white fish","shrimp-paste-free red curry paste","fish sauce","egg","sugar","green beans","lime zest","makrut lime leaves (optional)","neutral oil"]},{"component_id":"cucumber-relish","name":"sweet-sour cucumber relish (ajad)","made_in_recipe":true,"store_bought":false,"ingredients":["English cucumber","shallot","red chile","rice vinegar","sugar","kosher salt","warm water","cilantro"]},{"component_id":"jasmine-rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'ff662722f0d9cfecce6c55457cf91272f06bcaa75409eb8d4ac2650905bd6c29', 'flavorweave-catalog-package', 'catalog/thai-fish-cakes-cucumber-relish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-red-curry-kabocha_v1', 'rcp_thai-red-curry-kabocha', 'thai-red-curry-kabocha', 1, 'Thai Red Curry with Kabocha and Tofu', 'Kabocha squash and browned tofu simmered in a coconut red curry built from vegetarian Thai red curry paste — no fish sauce, no dairy.', 4, 20, 35, 55, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to brown tofu. Medium to bloom paste and simmer curry. Rice: covered simmer then rest. No oven.', 'Kabocha tender when pierced. Tofu golden on edges. Spinach wilted. Curry cohesive, coconut-red, not broken. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"thai-red-coconut-curry","name":"Thai red coconut curry","made_in_recipe":true,"store_bought":false,"ingredients":["coconut oil","vegetarian/vegan Thai red curry paste","full-fat coconut milk","water","light brown sugar","kosher salt","kabocha squash","red bell pepper","extra-firm tofu","baby spinach","lime juice","fresh Thai basil"]},{"component_id":"jasmine-rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["uncooked jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, '2364e9750ed832e7594c0822ca2e85374c133181a776e21555e6be1016782121', 'flavorweave-catalog-package', 'catalog/thai-red-curry-kabocha/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-turkey-larb-lettuce-wraps_v1', 'rcp_thai-turkey-larb-lettuce-wraps', 'thai-turkey-larb-lettuce-wraps', 1, 'Thai Turkey Larb Lettuce Wraps', 'Ground turkey cooked into fine crumbles and dressed warm with lime juice, fish sauce, and chile flakes, then tossed with shallots, scallions, a fistful of mint and cilantro, and nutty homemade toasted rice powder. Spooned into butter lettuce cups with cool cucumber. Bright, herby, and on the table in under 30 minutes.', 4, 10, 19, 29, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Stovetop only. Medium dry heat to toast the rice; medium-high for the turkey. Dressing goes in off the heat. No oven.', 'Rice powder deep golden and nutty; turkey in fine crumbles, no pink (165 F), liquid evaporated; herbs bright and just barely wilted from the residual warmth. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"toasted-rice-powder","name":"toasted rice powder (khao khua)","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice"]},{"component_id":"turkey-larb","name":"lime-chile turkey larb","made_in_recipe":true,"store_bought":false,"ingredients":["ground turkey","neutral oil","water","fish sauce","lime juice","sugar","dried chile flakes","shallots","scallions","fresh mint","cilantro","toasted rice powder"]},{"component_id":"wraps","name":"butter lettuce cups with cucumber and lime","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","English cucumber","lime wedges"]}]', 'published', 'draft', 'global', NULL, '84a1fec19cd634c18bcbf08672d7323e31ee8de49246b4b284de1f88447b4f88', 'flavorweave-catalog-package', 'catalog/thai-turkey-larb-lettuce-wraps/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_tomato-soup-grilled-cheese_v1', 'rcp_tomato-soup-grilled-cheese', 'tomato-soup-grilled-cheese', 1, 'Roasted Tomato Soup with Grilled Cheese', 'Silky soup of oven-roasted Roma tomatoes, onion, and garlic blended with vegetable broth, basil, and a splash of cream, served with golden, buttery sharp-cheddar grilled cheese on sourdough for dunking.', 4, 12, 44, 56, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven 450 F for roasting (upper-middle rack); medium-high to bring the soup to a simmer, then gentle; medium-low skillet for the grilled cheese.', 'Tomatoes slumped and blistered with browned edges; soup silky, no skins visible. Grilled cheese deep golden and crisp with fully melted cheese. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"roasted-tomato-soup","name":"roasted tomato soup","made_in_recipe":true,"store_bought":false,"ingredients":["Roma tomatoes","yellow onion","garlic","olive oil","kosher salt","black pepper","tomato paste","vegetable broth","fresh basil","heavy cream","sugar (optional)"]},{"component_id":"cheddar-grilled-cheese","name":"sharp cheddar grilled cheese on sourdough","made_in_recipe":true,"store_bought":false,"ingredients":["sourdough bread","sharp cheddar","unsalted butter"]}]', 'published', 'draft', 'global', NULL, '3675b8fe704bf39945743265cebfa5bf11ec06d70c812433902fc8938577e24a', 'flavorweave-catalog-package', 'catalog/tomato-soup-grilled-cheese/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_turkish-lahmacun_v1', 'rcp_turkish-lahmacun', 'turkish-lahmacun', 1, 'Turkish Lahmacun with Herb Salad', 'Thin flatbreads spread edge to edge with a spiced lamb, tomato, pepper, and parsley paste seasoned with Aleppo pepper and cumin, baked in a very hot oven until the rims crisp. Topped with a sumac red-onion, tomato, and parsley salad and a squeeze of lemon, then rolled up to eat. No cheese.', 4, 20, 32, 52, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Oven 475 F with an inverted rimmed sheet pan on the lowest rack, preheated 20 minutes during prep. Lahmacun start on parchment for 3 minutes, then finish directly on the hot pan; 7 to 8 minutes total per batch.', 'Flatbread rims and underside browned and crisp, still flexible enough to roll; topping sizzling, browned in spots, cooked through with no pink (160 F). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lamb-topping","name":"spiced lamb, tomato, and parsley paste","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","yellow onion","red bell pepper","Roma tomato","garlic","flat-leaf parsley","tomato paste","Aleppo pepper","ground cumin","kosher salt","black pepper","olive oil"]},{"component_id":"thin-flatbreads","name":"rolled thin flatbreads","made_in_recipe":true,"store_bought":false,"ingredients":["store-bought plain pizza dough","all-purpose flour"],"contract":"Store-bought plain pizza dough (no milk, egg, or cheese), rolled and baked in the recipe."},{"component_id":"sumac-herb-salad","name":"sumac onion, tomato, and parsley salad","made_in_recipe":true,"store_bought":false,"ingredients":["red onion","sumac","kosher salt","Roma tomatoes","flat-leaf parsley","lemon juice","olive oil","Aleppo pepper"]}]', 'published', 'draft', 'global', NULL, 'f43cb892cdb9fb31d75c1e0efcc4e9611b3f83adef4e498c0586c85f15c8b423', 'flavorweave-catalog-package', 'catalog/turkish-lahmacun/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vegetable-biryani-cashews_v1', 'rcp_vegetable-biryani-cashews', 'vegetable-biryani-cashews', 1, 'Vegetable Biryani with Saffron and Cashews', 'Long-grain basmati parboiled and steamed (dum) over a garam-masala vegetable base of cauliflower, carrots, and peas, streaked with saffron and layered with crisp-fried onions, mint, and toasted cashews. Oil instead of ghee; no yogurt, cream, or butter; cashews are the only nut.', 4, 20, 50, 70, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium oil for cashews, medium-high for onions, medium covered for vegetables, high boil for rice, then medium 2 minutes and lowest heat for the dum. No oven.', 'Onions deep golden and crisp. Rice grains long, separate, fully tender, streaked saffron-orange. Cauliflower tender but holding shape; no wet puddle at the bottom. Cashews golden. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"fried-onions-cashews","name":"crisp-fried onions (birista) and toasted cashews","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onions","raw cashews","neutral oil","kosher salt"]},{"component_id":"vegetable-masala","name":"garam-masala vegetable base","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","ginger","serrano","garam masala","turmeric","cauliflower","carrots","peas","lemon juice","mint","fried onions"]},{"component_id":"saffron-rice","name":"parboiled basmati with saffron water","made_in_recipe":true,"store_bought":false,"ingredients":["basmati rice","saffron","salted water","neutral oil","lemon juice","garam masala"]}]', 'published', 'draft', 'global', NULL, '3253b0e145c0043100a3774dc08d17254741fcde2c7b8f042682b5cc62e3c12a', 'flavorweave-catalog-package', 'catalog/vegetable-biryani-cashews/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-chicken-pho_v1', 'rcp_vietnamese-chicken-pho', 'vietnamese-chicken-pho', 1, 'Vietnamese Chicken Pho', 'Chicken simmered with charred onion, ginger, and whole spices into a clear broth, served over flat rice noodles with herbs and lime.', 4, 20, 55, 75, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', 'Dry medium-high skillet for charring. Stockpot: high to boil, then gentle simmer. No oven.', 'Chicken thighs 175 F near the bone before shredding. Broth clear, savory, lightly sweet. Rice noodles pliable, not mushy. Broth steaming hot in the bowl. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"pho-chicken-broth","name":"pho chicken broth","made_in_recipe":true,"store_bought":false,"ingredients":["bone-in chicken thighs","yellow onion","fresh ginger","star anise","cinnamon stick","whole cloves","coriander seeds","water","fish sauce","kosher salt","sugar"]}]', 'published', 'draft', 'global', NULL, 'e95da3c7cad2fce8166f2326670103288c555a8b667ba127add1045c3ea222ce', 'flavorweave-catalog-package', 'catalog/vietnamese-chicken-pho/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-turmeric-dill-fish_v1', 'rcp_vietnamese-turmeric-dill-fish', 'vietnamese-turmeric-dill-fish', 1, 'Vietnamese Turmeric Fish with Dill and Noodles', 'Chả cá–style catfish: bite-size pieces marinated in turmeric, ginger, shallot, and fish sauce, seared golden, then tossed with a big handful of dill and scallions wilted in the hot pan. Served over cool rice vermicelli with mint, chopped roasted cashews, red chile, and a bright lime nước chấm. No shrimp paste; cashews instead of peanuts.', 4, 20, 17, 37, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Stovetop only. Rolling boil for noodles; medium-high, shimmering oil for the sear and the quick dill wilt. No oven.', 'Fish deep golden on the seared side, opaque and flaking through (145 F); dill just wilted and still vivid green; noodles tender, rinsed cool, and not clumped. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"turmeric-catfish","name":"turmeric-ginger marinated seared catfish","made_in_recipe":true,"store_bought":false,"ingredients":["catfish","ground turmeric","fresh ginger","shallot","garlic","fish sauce","sugar","kosher salt","black pepper","neutral oil"]},{"component_id":"wilted-dill-scallions","name":"pan-wilted dill and scallions","made_in_recipe":true,"store_bought":false,"ingredients":["fresh dill","scallions","neutral oil"]},{"component_id":"nuoc-cham","name":"lime nước chấm","made_in_recipe":true,"store_bought":false,"ingredients":["fish sauce","lime juice","sugar","warm water","garlic","red chile"]},{"component_id":"noodles-and-toppings","name":"rice vermicelli with mint, cashews, and chile","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","fresh mint","roasted cashews","red chile","lime wedges"]}]', 'published', 'draft', 'global', NULL, '45176e2f2516c5246dc9d290d1fe31de379d189d35f88006287313018f74bd23', 'flavorweave-catalog-package', 'catalog/vietnamese-turmeric-dill-fish/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_white-bean-kale-soup_v1', 'rcp_white-bean-kale-soup', 'white-bean-kale-soup', 1, 'White Bean Kale Soup', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'a9025ee246a4283d9cb2a96e28336bec6c1aba93307c8fd5356588c4aac1a739', 'flavorweave-legacy-catalog-package', 'catalog/white-bean-kale-soup/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_white-bean-kale-soup_v2', 'rcp_white-bean-kale-soup', 'white-bean-kale-soup', 2, 'White Bean Kale Soup', 'Stovetop soup of cannellini beans, fennel, diced tomato, and kale in vegetable broth.', 4, 15, 30, 45, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Medium heat to soften the fennel, then a simmer. No oven.', 'Fennel is softened at 5 minutes. The soup simmers 20 minutes. Kale is tender at about 5 minutes more. Canned beans are already cooked.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'c9539f30ffe1a7ecd031159e2d87d845a77e7e18877c6fd1c65445d3776d3f7d', 'flavorweave-legacy-audit-draft', 'catalog/white-bean-kale-soup/v2.json', '2026-10-04T00:00:00.000Z');

